//! The methods' reference, as Markdown, from the registry's schemas: docs/api.md's generated part.
use crate::methods;
use serde_json::{Map, Value};
use std::fmt::Write;

/// The line docs/api.md's generated part starts after, and the one it ends before.
pub const BEGIN: &str =
    "<!-- generated by `mwcc-tools methods --markdown`: edit the schemas, not this -->";
pub const END: &str = "<!-- end of the generated reference -->";

/// A schema node's type, as a reader writes it: `string`, `integer`, `[string]`, `{string: X}`, a definition's
/// name, `"a" | "b"`, `any`; and whether it may be null.
fn type_of(node: &Value) -> (String, bool) {
    if let Some(reference) = node["$ref"].as_str() {
        return (
            reference.rsplit('/').next().unwrap_or(reference).into(),
            false,
        );
    }
    for key in ["anyOf", "oneOf"] {
        if let Some(options) = node[key].as_array() {
            let mut nullable = false;
            let mut names = vec![];
            for option in options {
                if option["type"] == "null" {
                    nullable = true;
                } else {
                    let (name, null) = type_of(option);
                    nullable |= null;
                    names.push(name);
                }
            }
            return (names.join(" | "), nullable);
        }
    }
    if let Some(values) = node["enum"].as_array() {
        let nullable = values.iter().any(Value::is_null);
        return (
            values
                .iter()
                .filter(|v| !v.is_null())
                .map(Value::to_string)
                .collect::<Vec<_>>()
                .join(" | "),
            nullable,
        );
    }
    if let Some(constant) = node.get("const") {
        return (constant.to_string(), false);
    }
    let (types, nullable): (Vec<&str>, bool) = match &node["type"] {
        Value::String(t) => (vec![t.as_str()], false),
        Value::Array(ts) => {
            let all: Vec<&str> = ts.iter().filter_map(Value::as_str).collect();
            (
                all.iter().copied().filter(|t| *t != "null").collect(),
                all.contains(&"null"),
            )
        }
        _ => (vec![], false),
    };
    let named: Vec<String> = types
        .iter()
        .map(|t| match *t {
            "array" => match node.get("items") {
                Some(items) => format!("[{}]", type_of(items).0),
                None => "[any]".into(),
            },
            "object" => match node.get("additionalProperties") {
                Some(Value::Bool(false)) | None => "object".into(),
                Some(Value::Bool(true)) => "{string: any}".into(),
                Some(values) => format!("{{string: {}}}", type_of(values).0),
            },
            other => other.into(),
        })
        .collect();
    if named.is_empty() {
        ("any".into(), nullable)
    } else {
        (named.join(" | "), nullable)
    }
}

/// One line of text: a description's paragraphs joined, and its pipes escaped.
fn cell(text: &str) -> String {
    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace('|', "\\|")
}

/// KIND in code, with the names of TYPES linked to their entries.
fn linked(kind: &str, types: &Types) -> String {
    // (runs of plain text in code spans, each linked name its own: `[`, [`Side`](#type-side), `]`)
    let mut out = String::new();
    let mut plain = String::new();
    let flush = |plain: &mut String, out: &mut String| {
        if !plain.trim().is_empty() {
            let _ = write!(out, "`{}`", plain.trim().replace('|', "\\|"));
        }
        plain.clear();
    };
    let mut rest = kind;
    while !rest.is_empty() {
        let end = rest
            .find(|c: char| !(c.is_alphanumeric() || c == '_'))
            .unwrap_or(rest.len());
        let (word, after) = if end == 0 {
            let width = rest.chars().next().unwrap().len_utf8();
            rest.split_at(width)
        } else {
            rest.split_at(end)
        };
        match types.anchor(word) {
            Some(anchor) => {
                flush(&mut plain, &mut out);
                let _ = write!(out, "[`{word}`](#{anchor})");
            }
            None => plain.push_str(word),
        }
        rest = after;
    }
    flush(&mut plain, &mut out);
    out
}

/// The definitions the schemas name: each name's schema and its anchor (a name two schemas define differently gets
/// a numbered anchor per schema).
#[derive(Default)]
struct Types {
    entries: Vec<(String, String, Value)>,
}

impl Types {
    fn add(&mut self, name: &str, schema: &Value) -> String {
        if let Some((_, anchor, _)) = self
            .entries
            .iter()
            .find(|(n, _, s)| n == name && s == schema)
        {
            return anchor.clone();
        }
        let same = self.entries.iter().filter(|(n, _, _)| n == name).count();
        let anchor = if same == 0 {
            format!("type-{}", name.to_lowercase())
        } else {
            format!("type-{}-{}", name.to_lowercase(), same + 1)
        };
        self.entries
            .push((name.to_owned(), anchor.clone(), schema.clone()));
        anchor
    }

    /// NAME's anchor, when one schema defines it (a name defined differently is not linked).
    fn anchor(&self, name: &str) -> Option<&str> {
        let mut found = self.entries.iter().filter(|(n, _, _)| n == name);
        let first = found.next()?;
        found.next().is_none().then_some(first.1.as_str())
    }
}

/// The fields of an object schema, as a table.
fn fields(out: &mut String, object: &Value, types: &Types) {
    let Some(properties) = object["properties"].as_object() else {
        let (name, _) = type_of(object);
        let _ = writeln!(out, "{}\n", linked(&name, types));
        return;
    };
    if properties.is_empty() {
        out.push_str("none\n\n");
        return;
    }
    let required: Vec<&str> = object["required"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect();
    out.push_str("| field | type | |\n|---|---|---|\n");
    for (name, node) in properties {
        let (kind, nullable) = type_of(node);
        let mut notes = vec![];
        if required.contains(&name.as_str()) && !nullable {
            notes.push("**required**".to_owned());
        }
        if let Some(default) = node.get("default")
            && !default.is_null()
            && *default != Value::Bool(false)
            && *default != Value::Object(Map::new())
            && *default != Value::Array(vec![])
        {
            notes.push(format!("default `{default}`"));
        }
        if let Some(description) = node["description"].as_str() {
            notes.push(cell(description));
        }
        let _ = writeln!(
            out,
            "| `{name}` | {} | {} |",
            linked(&kind, types),
            notes.join("; ")
        );
    }
    out.push('\n');
}

/// The reference: the methods by namespace (each one's summary, parameters and result), then the types they name.
pub fn markdown() -> String {
    let mut types = Types::default();
    for method in methods() {
        for schema in [(method.params)(), (method.result)()] {
            for (name, node) in schema["$defs"].as_object().into_iter().flatten() {
                types.add(name, node);
            }
        }
    }
    let mut spaces: Vec<&str> = vec![];
    for method in methods() {
        let space = method.name.split('.').next().unwrap_or(method.name);
        if !spaces.contains(&space) {
            spaces.push(space);
        }
    }
    let mut out = String::new();
    for space in spaces {
        let _ = writeln!(out, "### {space}\n");
        for method in methods()
            .iter()
            .filter(|m| m.name.split('.').next() == Some(space))
        {
            let _ = writeln!(out, "#### `{}`\n\n{}.\n", method.name, method.summary);
            out.push_str("Parameters:\n\n");
            fields(&mut out, &(method.params)(), &types);
            out.push_str("Result:\n\n");
            fields(&mut out, &(method.result)(), &types);
        }
    }
    out.push_str("### Types\n\n");
    let mut entries: Vec<_> = types.entries.iter().collect();
    entries.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    for (name, anchor, node) in entries {
        let _ = write!(out, "<a id=\"{anchor}\"></a>**`{name}`**");
        if let Some(description) = node["description"].as_str() {
            let _ = write!(out, ": {}", cell(description));
        }
        out.push_str("\n\n");
        fields(&mut out, node, &types);
    }
    out.trim_end().to_owned() + "\n"
}

/// DOCUMENT with its generated part replaced by the reference.
pub fn updated(document: &str) -> Option<String> {
    let start = document.find(BEGIN)? + BEGIN.len();
    let end = document[start..].find(END)? + start;
    Some(format!(
        "{}\n\n{}\n{}",
        &document[..start],
        markdown(),
        &document[end..]
    ))
}
